а?", "kk": "Бағдаршамның сары сигналында не істеу керек?"}, "options": [{"ru": "Ускориться", "kk": "Жылдамдау"}, {"ru": "Игнорировать", "kk": "Елемеу"}, {"ru": "Остановиться, если можно безопасно", "kk": "Қауіпсіз болса тоқтау"}], "correct": 2, "explain": {"ru": "Жёлтый предупреждает о смене сигнала.", "kk": "Сары сигналдың ауысатынын ескертеді."}}, {"id": "q_pdd_042", "q": {"ru": "Разрешён ли обгон справа?", "kk": "Оң жақтан басып озуға рұқсат па?"}, "options": [{"ru": "Да, всегда", "kk": "Иә, әрқашан"}, {"ru": "Только на автомагистрали", "kk": "Тек автомагистральда"}, {"ru": "Нет, обгон слева", "kk": "Жоқ, басып озу сол жақтан"}], "correct": 2, "explain": {"ru": "Обгон выполняется слева.", "kk": "Басып озу сол жақтан орындалады."}}, {"id": "q_pdd_043", "q": {"ru": "Как подать сигнал о намерении повернуть?", "kk": "Бұрылу ниеті туралы қалай сигнал беру керек?"}, "options": [{"ru": "Не нужно", "kk": "Қажет емес"}, {"ru": "После поворота", "kk": "Бұрылғаннан кейін"}, {"ru": "Рукой или поворотником заблаговременно", "kk": "Қолмен немесе бұрылыс сигналымен алдын ала"}], "correct": 2, "explain": {"ru": "Сигнал подаётся заранее.", "kk": "Сигнал алдын ала беріледі."}}, {"id": "q_pdd_044", "q": {"ru": "Что такое безопасная дистанция?", "kk": "Қауіпсіз арақашықтық деген не?"}, "options": [{"ru": "Минимум 1 метр", "kk": "Кемінде 1 метр"}, {"ru": "Расстояние, позволяющее избежать столкновения при торможении", "kk": "Тежеу кезінде соқтығысудан аулақ болуға мүмкіндік беретін қашықтық"}, {"ru": "Любое", "kk": "Кез келген"}], "correct": 1, "explain": {"ru": "Дистанция должна позволять остановиться безопасно.", "kk": "Арақашықтық қауіпсіз тоқтауға мүмкіндік беруі керек."}}, {"id": "q_pdd_045", "q": {"ru": "Можно ли останавливаться на пешеходном переходе?", "kk": "Жаяу өткелде тоқтауға бола ма?"}, "options": [{"ru": "Нет", "kk": "Жоқ"}, {"ru": "Да", "kk": "Иә"}, {"ru": "Только на 5 минут", "kk": "Тек 5 минут"}], "correct": 0, "explain": {"ru": "Остановка на переходе запрещена.", "kk": "Өткелде тоқтауға тыйым."}}, {"id": "q_pdd_046", "q": {"ru": "Как проезжать нерегулируемый перекрёсток равнозначных дорог?", "kk": "Тең жолдардың реттелмейтін қиылысын қалай өту керек?"}, "options": [{"ru": "Уступить помехе справа", "kk": "Оң жақтағы кедергіге жол беру"}, {"ru": "Кто быстрее", "kk": "Кім жылдам"}, {"ru": "Всегда ехать", "kk": "Әрқашан жүру"}], "correct": 0, "explain": {"ru": "Действует правило помехи справа.", "kk": "Оң жақтағы кедергі ережесі қолданылады."}}, {"id": "q_pdd_047", "q": {"ru": "Кто имеет преимущество на главной дороге?", "kk": "Басты жолда кімнің басымдығы бар?"}, "options": [{"ru": "Пешеход всегда", "kk": "Жаяу жүргінші әрқашан"}, {"ru": "Тот, кто справа", "kk": "Оң жақтағы"}, {"ru": "Тот, кто на главной", "kk": "Басты жолдағы"}], "correct": 2, "explain": {"ru": "На главной дороге преимущество у движущегося по ней.", "kk": "Басты жолда басымдық сол жолмен жүретінде."}}, {"id": "q_pdd_048", "q": {"ru": "Можно ли поворачивать налево с правой полосы?", "kk": "Оң жолақтан солға бұрылуға бола ма?"}, "options": [{"ru": "Если нет знаков", "kk": "Белгі болмаса"}, {"ru": "Нет, только с левой", "kk": "Жоқ, тек сол жолақтан"}, {"ru": "Да", "kk": "Иә"}], "correct": 1, "explain": {"ru": "Поворот налево — с крайней левой полосы.", "kk": "Солға бұрылу — ең сол жолақтан."}}, {"id": "q_pdd_049", "q": {"ru": "Как правильно разворачиваться?", "kk": "Қалай дұрыс бұрылу керек?"}, "options": [{"ru": "Задним ходом", "kk": "Артқа жүріп"}, {"ru": "С любой полосы", "kk": "Кез келген жолақтан"}, {"ru": "С крайней левой полосы, убедившись в безопасности", "kk": "Ең сол жолақтан, қауіпсіздікті тексеріп"}], "correct": 2, "explain": {"ru": "Разворот с крайней левой полосы.", "kk": "Бұрылу ең сол жолақтан."}}, {"id": "q_pdd_050", "q": {"ru": "Что делать, если заглох двигатель на переезде?", "kk": "Өткелде қозғалтқыш өшсе не істеу керек?"}, "options": [{"ru": "Немедленно эвакуировать авто и предупредить других", "kk": "Көлікті дереу эвакуациялап, басқаларды ескерту"}, {"ru": "Сигналить", "kk": "Сигнал беру"}, {"ru": "Ждать", "kk": "Күту"}], "correct": 0, "explain": {"ru": "Нужно быстро убрать автомобиль с переезда.", "kk": "Көлікті өткелден тез алып тастау керек."}}, {"id": "q_pdd_051", "q": {"ru": "Разрешена ли остановка на мосту?", "kk": "Көпірде тоқтауға рұқсат па?"}, "options": [{"ru": "Да", "kk": "Иә"}, {"ru": "Только ночью", "kk": "Тек түнде"}, {"ru": "Нет", "kk": "Жоқ"}], "correct": 2, "explain": {"ru": "Остановка на мосту запрещена.", "kk": "Көпірде тоқтауға тыйым."}}, {"id": "q_pdd_052", "q": {"ru": "Как буксировать автомобиль?", "kk": "Автокөлікті қалай сүйреу керек?"}, "options": [{"ru": "На гибкой или жёсткой сцепке по правилам", "kk": "Икемді немесе қатты ілініспен ереже бойынша"}, {"ru": "Как угодно", "kk": "Қалағанша"}, {"ru": "Только ночью", "kk": "Тек түнде"}], "correct": 0, "explain": {"ru": "Буксировка выполняется по установленным правилам.", "kk": "Сүйреу белгіленген ереже бойынша орындалады."}}, {"id": "q_pdd_053", "q": {"ru": "Можно ли обгонять тихоходное ТС?", "kk": "Баяу жүретін көлікті басып озуға бола ма?"}, "options": [{"ru": "Только справа", "kk": "Тек оң жақтан"}, {"ru": "Да, если безопасно и не запрещено знаком", "kk": "Иә, қауіпсіз болса және белгімен тыйым салынбаса"}, {"ru": "Никогда", "kk": "Ешқашан"}], "correct": 1, "explain": {"ru": "Обгон тихохода разрешён при безопасности.", "kk": "Баяу көлікті басып озу қауіпсіз болса рұқсат."}}, {"id": "q_pdd_054", "q": {"ru": "Что такое «помеха справа»?", "kk": "«Оң жақтағы кедергі» деген не?"}, "options": [{"ru": "Преимущество у того, кто слева", "kk": "Басымдық сол жақтағыда"}, {"ru": "Преимущество у того, кто справа", "kk": "Басымдық оң жақтағыда"}, {"ru": "Нет такого правила", "kk": "Мұндай ереже жоқ"}], "correct": 1, "explain": {"ru": "На равнозначных дорогах уступают помехе справа.", "kk": "Тең жолдарда оң жақтағы кедергіге жол береді."}}, {"id": "q_pdd_055", "q": {"ru": "Где нельзя останавливаться?", "kk": "Қайда тоқтауға болмайды?"}, "options": [{"ru": "На переходе, перекрёстке, ж/д переезде", "kk": "Өткелде, қиылыста, теміржол өткелінде"}, {"ru": "На стоянке", "kk": "Тұрақта"}, {"ru": "У тротуара", "kk": "Жол жиегінде"}], "correct": 0, "explain": {"ru": "Остановка запрещена в указанных местах.", "kk": "Көрсетілген орындарда тоқтауға тыйым."}}, {"id": "q_pdd_056", "q": {"ru": "Как проехать круговое движение?", "kk": "Айналма қозғалысты қалай өту керек?"}, "options": [{"ru": "Ехать против часовой", "kk": "Сағат тіліне қарсы"}, {"ru": "Уступить уже движущимся по кругу, если не указано иное", "kk": "Басқаша көрсетілмесе, шеңберде жүріп жатқандарға жол беру"}, {"ru": "Въезжающий имеет преимущество всегда", "kk": "Кіретін әрқашан басым"}], "correct": 1, "explain": {"ru": "Обычно уступают тем, кто уже на круге.", "kk": "Әдетте шеңбердегілерге жол береді."}}, {"id": "q_pdd_057", "q": {"ru": "Разрешён ли разворот на автомагистрали?", "kk": "Автомагистральда бұрылуға рұқсат па?"}, "options": [{"ru": "Да", "kk": "Иә"}, {"ru": "Только на развязке", "kk": "Тек айырықта"}, {"ru": "Нет", "kk": "Жоқ"}], "correct": 2, "explain": {"ru": "Разворот на автомагистрали запрещён.", "kk": "Автомагистральда бұрылуға тыйым."}}, {"id": "q_pdd_058", "q": {"ru": "Можно ли останавливаться на автомагистрали?", "kk": "Автомагистральда тоқтауға бола ма?"}, "options": [{"ru": "Да, где угодно", "kk": "Иә, қалаған жерде"}, {"ru": "Только на специально отведённых местах", "kk": "Тек арнайы орындарда"}, {"ru": "На обочине всегда", "kk": "Жол жиегінде әрқашан"}], "correct": 1, "explain": {"ru": "Остановка только в разрешённых местах.", "kk": "Тоқтау тек рұқсат етілген орындарда."}}, {"id": "q_pdd_059", "q": {"ru": "Как двигаться в тоннеле?", "kk": "Туннельде қалай жүру керек?"}, "options": [{"ru": "С включённым ближним светом, без остановки", "kk": "Жақын жарық қосылып, тоқтаусыз"}, {"ru": "Без света", "kk": "Жарықсыз"}, {"ru": "Можно останавливаться", "kk": "Тоқтауға болады"}], "correct": 0, "explain": {"ru": "В тоннеле — ближний свет, остановка запрещена.", "kk": "Туннельде — жақын жарық, тоқтау тыйым."}}, {"id": "q_pdd_060", "q": {"ru": "Что делать при заносе?", "kk": "Сырғанау кезінде не істеу керек?"}, "options": [{"ru": "Плавно скорректировать руль в сторону заноса", "kk": "Рөлді сырғанау бағытына жұмсақ түзету"}, {"ru": "Резко тормозить", "kk": "Күрт тежеу"}, {"ru": "Газовать", "kk": "Газ беру"}], "correct": 0, "explain": {"ru": "При заносе руль поворачивают в сторону заноса.", "kk": "Сырғанауда рөлді сырғанау бағытына бұрады."}}, {"id": "q_pdd_061", "q": {"ru": "Можно ли использовать телефон за рулём?", "kk": "Рөлде телефонды пайдалануға бола ма?"}, "options": [{"ru": "Нет, без hands-free", "kk": "Жоқ, hands-free-сыз"}, {"ru": "Да", "kk": "Иә"}, {"ru": "Только на красный", "kk": "Тек қызылда"}], "correct": 0, "explain": {"ru": "Разговор по телефону без гарнитуры запрещён.", "kk": "Гарнитурасыз телефонмен сөйлесуге тыйым."}}, {"id": "q_pdd_062", "q": {"ru": "Какой свет использовать ночью вне населённого пункта?", "kk": "Елді мекеннен тыс түнде қандай жарық қолдану керек?"}, "options": [{"ru": "Габариты", "kk": "Габарит"}, {"ru": "Аварийка", "kk": "Апат сигналы"}, {"ru": "Дальний, если нет встречных", "kk": "Қарсы келетіндер болмаса, алыс жарық"}], "correct": 2, "explain": {"ru": "Ночью вне города — дальний при отсутствии встречных.", "kk": "Түнде қала сыртында — қарсы келетіндер болмаса алыс жарық."}}, {"id": "q_pdd_063", "q": {"ru": "Когда включать ближний свет днём?", "kk": "Күндіз жақын жарықты қашан қосу керек?"}, "options": [{"ru": "Только ночью", "kk": "Тек түнде"}, {"ru": "Никогда", "kk": "Ешқашан"}, {"ru": "При недостаточной видимости и по правилам", "kk": "Көріну нашар болғанда және ереже бойынша"}], "correct": 2, "explain": {"ru": "Ближний включают при плохой видимости и где требуется.", "kk": "Жақын жарықты көріну нашар болғанда және талап етілгенде қосады."}}, {"id": "q_pdd_064", "q": {"ru": "Как обогнать велосипедиста?", "kk": "Велосипедшіні қалай басып озу керек?"}, "options": [{"ru": "Сигналя", "kk": "Сигнал беріп"}, {"ru": "Вплотную", "kk": "Жақын"}, {"ru": "С безопасным боковым интервалом", "kk": "Қауіпсіз бүйірлік аралықпен"}], "correct": 2, "explain": {"ru": "Нужен достаточный боковой интервал.", "kk": "Жеткілікті бүйірлік аралық керек."}}, {"id": "q_pdd_065", "q": {"ru": "Можно ли двигаться по обочине?", "kk": "Жол жиегімен жүруге бола ма?"}, "options": [{"ru": "Да, всегда", "kk": "Иә, әрқашан"}, {"ru": "Только грузовикам", "kk": "Тек жүк көліктеріне"}, {"ru": "Нет, кроме случаев, предусмотренных правилами", "kk": "Жоқ, ережеде көзделген жағдайлардан басқа"}], "correct": 2, "explain": {"ru": "Движение по обочине запрещено, кроме исключений.", "kk": "Жол жиегімен жүруге тыйым, ерекшеліктерден басқа."}}, {"id": "q_pdd_066", "q": {"ru": "Что такое «мёртвая зона»?", "kk": "«Өлі аймақ» деген не?"}, "options": [{"ru": "Парковка", "kk": "Тұрақ"}, {"ru": "Пешеходный переход", "kk": "Жаяу өткел"}, {"ru": "Зона, не видимая в зеркалах", "kk": "Айналарда көрінбейтін аймақ"}], "correct": 2, "explain": {"ru": "Мёртвая зона — участок, не видимый в зеркалах.", "kk": "Өлі аймақ — айналарда көрінбейтін учаске."}}, {"id": "q_pdd_067", "q": {"ru": "Как правильно парковаться параллельно?", "kk": "Параллель қалай дұрыс тұраққа қою керек?"}, "options": [{"ru": "Носом к бордюру", "kk": "Мұрынмен бордюрге"}, {"ru": "Задним ходом, контролируя расстояние", "kk": "Артқа жүріп, қашықтықты бақылап"}, {"ru": "Поперёк", "kk": "Көлденең"}], "correct": 1, "explain": {"ru": "Параллельная парковка обычно задним ходом.", "kk": "Параллель тұрақ әдетте артқа жүріп."}}, {"id": "q_pdd_068", "q": {"ru": "Разрешён ли обгон на подъёме?", "kk": "Көтерілісте басып озуға рұқсат па?"}, "options": [{"ru": "Да", "kk": "Иә"}, {"ru": "Нет, в конце подъёма", "kk": "Жоқ, көтерілістің соңында"}, {"ru": "Только ночью", "kk": "Тек түнде"}], "correct": 1, "explain": {"ru": "В конце подъёма обгон опасен и запрещён.", "kk": "Көтерілістің соңында басып озу қауіпті және тыйым."}}, {"id": "q_pdd_069", "q": {"ru": "Что делать при приближении спецтранспорта с включёнными сигналами?", "kk": "Сигналдары қосылған арнайы көлік жақындағанда не істеу керек?"}, "options": [{"ru": "Уступить дорогу и остановиться при необходимости", "kk": "Жол беріп, қажет болса тоқтау"}, {"ru": "Продолжать движение", "kk": "Қозғалысты жалғастыру"}, {"ru": "Обгонять", "kk": "Басып озу"}], "correct": 0, "explain": {"ru": "Спецтранспорту с маячками нужно уступать.", "kk": "Маяктары бар арнайы көлікке жол беру керек."}}, {"id": "q_pdd_070", "q": {"ru": "Можно ли открывать двери на проезжей части без проверки?", "kk": "Жол бөлігінде есікті тексерусіз ашуға бола ма?"}, "options": [{"ru": "Только пассажиру", "kk": "Тек жолаушыға"}, {"ru": "Нет, нужно убедиться в безопасности", "kk": "Жоқ, қауіпсіздікті тексеру керек"}, {"ru": "Да", "kk": "Иә"}], "correct": 1, "explain": {"ru": "Перед открытием двери проверяют обстановку.", "kk": "Есікті ашпас бұрын жағдайды тексереді."}}, {"id": "q_pdd_071", "q": {"ru": "Кто проедет первым на регулируемом перекрёстке?", "kk": "Реттелетін қиылыста кім бірінші өтеді?"}, "options": [{"ru": "Кто по главной", "kk": "Басты жолдағы"}, {"ru": "Кто справа", "kk": "Оң жақтағы"}, {"ru": "Кто по сигналу светофора", "kk": "Бағдаршам сигналы бойынша"}], "correct": 2, "explain": {"ru": "На регулируемом — по светофору.", "kk": "Реттелетінде — бағдаршам бойынша."}}, {"id": "q_pdd_072", "q": {"ru": "Что означает зелёная стрелка в дополнительной секции?", "kk": "Қосымша секциядағы жасыл жебе нені білдіреді?"}, "options": [{"ru": "Обгон", "kk": "Басып озу"}, {"ru": "Стоп", "kk": "Тоқта"}, {"ru": "Движение в направлении стрелки разрешено", "kk": "Жебе бағытында қозғалыс рұқсат"}], "correct": 2, "explain": {"ru": "Стрелка разрешает движение в своём направлении.", "kk": "Жебе өз бағытында қозғалысқа рұқсат береді."}}, {"id": "q_pdd_073", "q": {"ru": "Можно ли поворачивать направо на красный?", "kk": "Қызылда оңға бұрылуға бола ма?"}, "options": [{"ru": "Да, всегда", "kk": "Иә, әрқашан"}, {"ru": "Никогда", "kk": "Ешқашан"}, {"ru": "Только если есть разрешающая стрелка", "kk": "Тек рұқсат беретін жебе болса"}], "correct": 2, "explain": {"ru": "На красный направо — только по стрелке.", "kk": "Қызылда оңға — тек жебе бойынша."}}, {"id": "q_pdd_074", "q": {"ru": "Как проезжать перекрёсток с круговым движением при знаке «Уступите дорогу»?", "kk": "«Жол беріңіз» белгісі бар айналма қиылысты қалай өту керек?"}, "options": [{"ru": "Уступить движущимся по кругу", "kk": "Шеңберде жүріп жатқандарға жол беру"}, {"ru": "Иметь преимущество", "kk": "Басымдыққа ие болу"}, {"ru": "Въезжать без остановки", "kk": "Тоқтамай кіру"}], "correct": 0, "explain": {"ru": "Знак обязывает уступить.", "kk": "Белгі жол беруді міндеттейді."}}, {"id": "q_pdd_075", "q": {"ru": "Что делать, если светофор не работает?", "kk": "Бағдаршам жұмыс істемесе не істеу керек?"}, "options": [{"ru": "Ехать как на главной", "kk": "Басты жолдағыдай жүру"}, {"ru": "Ждать", "kk": "Күту"}, {"ru": "Руководствоваться знаками приоритета и правилами нерегулируемого перекрёстка", "kk": "Басымдық белгілері мен реттелмейтін қиылыс ережелеріне сүйену"}], "correct": 2, "explain": {"ru": "При неработающем светофоре — знаки и общие правила.", "kk": "Жұмыс істемейтін бағдаршамда — белгілер мен жалпы ережелер."}}, {"id": "q_pdd_076", "q": {"ru": "Кто уступает при повороте налево?", "kk": "Солға бұрылғанда кім жол береді?"}, "options": [{"ru": "Встречный, едущий прямо", "kk": "Тіке келе жатқан қарсы"}, {"ru": "Вы уступаете встречному прямо и направо", "kk": "Сіз тіке және оңға келе жатқан қарсыға жол бересіз"}, {"ru": "Никто", "kk": "Ешкім"}], "correct": 1, "explain": {"ru": "При левом повороте уступают встречным.", "kk": "Солға бұрылғанда қарсы келетіндерге жол береді."}}, {"id": "q_pdd_077", "q": {"ru": "Можно ли въезжать на перекрёсток, если за ним затор?", "kk": "Артында кептеліс болса қиылысқа кіруге бола ма?"}, "options": [{"ru": "Нет, если придётся остановиться на перекрёстке", "kk": "Жоқ, қиылыста тоқтауға тура келсе"}, {"ru": "Только налево", "kk": "Тек солға"}, {"ru": "Да", "kk": "Иә"}], "correct": 0, "explain": {"ru": "Нельзя создавать затор на перекрёстке.", "kk": "Қиылыста кептеліс туғызуға болмайды."}}, {"id": "q_pdd_078", "q": {"ru": "Что означает красный с жёлтым сигнал?", "kk": "Қызыл мен сары сигнал нені білдіреді?"}, "options": [{"ru": "Можно ехать", "kk": "Жүруге болады"}, {"ru": "Скоро включится зелёный, готовьтесь", "kk": "Жақында жасыл қосылады, дайындалыңыз"}, {"ru": "Стоп навсегда", "kk": "Мәңгі тоқта"}], "correct": 1, "explain": {"ru": "Красный+жёлтый предупреждает о включении зелёного.", "kk": "Қызыл+сары жасылдың қосылатынын ескертеді."}}, {"id": "q_pdd_079", "q": {"ru": "Как действовать на Т-образном перекрёстке?", "kk": "Т-тәрізді қиылыста қалай әрекет ету керек?"}, "options": [{"ru": "По знакам приоритета или помехе справа", "kk": "Басымдық белгілері немесе оң кедергі бойынша"}, {"ru": "Всегда уступать", "kk": "Әрқашан жол беру"}, {"ru": "Всегда прямо", "kk": "Әрқашан тіке"}], "correct": 0, "explain": {"ru": "Приоритет определяется знаками или правилом помехи справа.", "kk": "Басымдық белгілермен немесе оң кедергі ережесімен анықталады."}}, {"id": "q_pdd_080", "q": {"ru": "Разрешён ли обгон на перекрёстке?", "kk": "Қиылыста басып озуға рұқсат па?"}, "options": [{"ru": "Нет на нерегулируемом", "kk": "Реттелмейтінде жоқ"}, {"ru": "Только справа", "kk": "Тек оң жақтан"}, {"ru": "Да", "kk": "Иә"}], "correct": 0, "explain": {"ru": "На нерегулируемом перекрёстке обгон запрещён.", "kk": "Реттелмейтін қиылыста басып озуға тыйым."}}, {"id": "q_pdd_081", "q": {"ru": "Что означает мигающий зелёный?", "kk": "Жыпылықтаған жасыл нені білдіреді?"}, "options": [{"ru": "Можно ускоряться", "kk": "Жылдамдауға болады"}, {"ru": "Скоро включится жёлтый, готовьтесь остановиться", "kk": "Жақында сары қосылады, тоқтауға дайындалыңыз"}, {"ru": "Стоп", "kk": "Тоқта"}], "correct": 1, "explain": {"ru": "Мигающий зелёный предупреждает о смене сигнала.", "kk": "Жыпылықтаған жасыл сигналдың ауысатынын ескертеді."}}, {"id": "q_pdd_082", "q": {"ru": "Кто имеет преимущество — трамвай или автомобиль на равнозначном перекрёстке?", "kk": "Тең қиылыста трамвайдың ба, автокөліктің ба басымдығы бар?"}, "options": [{"ru": "Кто быстрее", "kk": "Кім жылдам"}, {"ru": "Автомобиль", "kk": "Автокөлік"}, {"ru": "Трамвай", "kk": "Трамвай"}], "correct": 2, "explain": {"ru": "Трамвай имеет преимущество на равнозначных дорогах.", "kk": "Тең жолдарда трамвайдың басымдығы бар."}}, {"id": "q_pdd_083", "q": {"ru": "Как повернуть направо?", "kk": "Оңға қалай бұрылу керек?"}, "options": [{"ru": "С любой", "kk": "Кез келгеннен"}, {"ru": "С левой", "kk": "Сол жақтан"}, {"ru": "С крайней правой полосы", "kk": "Ең оң жолақтан"}], "correct": 2, "explain": {"ru": "Правый поворот — с крайней правой полосы.", "kk": "Оң бұрылыс — ең оң жолақтан."}}, {"id": "q_pdd_084", "q": {"ru": "Что делать, если регулировщик поднял руку вверх?", "kk": "Реттеуші қолын жоғары көтерсе не істеу керек?"}, "options": [{"ru": "Поворачивать", "kk": "Бұрылу"}, {"ru": "Остановиться (сигнал соответствует жёлтому)", "kk": "Тоқтау (сигнал сарыға сәйкес)"}, {"ru": "Ехать", "kk": "Жүру"}], "correct": 1, "explain": {"ru": "Поднятая рука — запрет движения.", "kk": "Көтерілген қол — қозғалысқа тыйым."}}, {"id": "q_pdd_085", "q": {"ru": "Как проезжать перекрёсток при работающем регулировщике?", "kk": "Реттеуші жұмыс істегенде қиылысты қалай өту керек?"}, "options": [{"ru": "По светофору", "kk": "Бағдаршам бойынша"}, {"ru": "По знакам", "kk": "Белгілер бойынша"}, {"ru": "По сигналам регулировщика, они главнее", "kk": "Реттеуші сигналдары бойынша, олар басым"}], "correct": 2, "explain": {"ru": "Сигналы регулировщика имеют приоритет.", "kk": "Реттеуші сигналдарының басымдығы бар."}}, {"id": "q_pdd_086", "q": {"ru": "Можно ли останавливаться за стоп-линией?", "kk": "Стоп-сызығынан кейін тоқтауға бола ма?"}, "options": [{"ru": "Да", "kk": "Иә"}, {"ru": "Где угодно", "kk": "Қалаған жерде"}, {"ru": "Нет,