, {"ru": "Уступите", "kk": "Жол беріңіз"}], "correct": 1, "explain": {"ru": "Белый фон на знаке главной дороги.", "kk": "Басты жол белгісіндегі ақ фон."}}, {"id": "q_pdd_114", "q": {"ru": "Как правильно уступать пешеходу?", "kk": "Жаяу жүргіншіге қалай дұрыс жол беру керек?"}, "options": [{"ru": "Сигналить", "kk": "Сигнал беру"}, {"ru": "Снизить скорость или остановиться и дать пройти", "kk": "Жылдамдықты төмендетіп немесе тоқтап, өтуге мүмкіндік беру"}, {"ru": "Объехать", "kk": "Айналып өту"}], "correct": 1, "explain": {"ru": "Нужно остановиться и пропустить.", "kk": "Тоқтап, өткізу керек."}}, {"id": "q_pdd_115", "q": {"ru": "Разрешена ли стоянка на газоне?", "kk": "Көгалда тұраққа рұқсат па?"}, "options": [{"ru": "Да", "kk": "Иә"}, {"ru": "Только ночью", "kk": "Тек түнде"}, {"ru": "Нет", "kk": "Жоқ"}], "correct": 2, "explain": {"ru": "Стоянка на газоне запрещена.", "kk": "Көгалда тұраққа тыйым."}}, {"id": "q_pdd_116", "q": {"ru": "Что такое «ослепление» фарами?", "kk": "Фарамен «соқыр ету» деген не?"}, "options": [{"ru": "Встречный дальний свет мешает видеть", "kk": "Қарсы алыс жарық көруге кедергі"}, {"ru": "Туман", "kk": "Тұман"}, {"ru": "Нормальный свет", "kk": "Қалыпты жарық"}], "correct": 0, "explain": {"ru": "При ослеплении нужно снизить скорость и остановиться.", "kk": "Соқыр еткенде жылдамдықты төмендетіп, тоқтау керек."}}, {"id": "q_pdd_117", "q": {"ru": "Как действовать при ослеплении?", "kk": "Соқыр еткенде қалай әрекет ету керек?"}, "options": [{"ru": "Сигналить", "kk": "Сигнал беру"}, {"ru": "Продолжать с той же скоростью", "kk": "Сол жылдамдықпен жалғастыру"}, {"ru": "Включить аварийку, снизить скорость, при необходимости остановиться", "kk": "Апат сигналын қосып, жылдамдықты төмендетіп, қажет болса тоқтау"}], "correct": 2, "explain": {"ru": "При ослеплении — аварийка и снижение скорости.", "kk": "Соқыр еткенде — апат сигналы және жылдамдықты төмендету."}}, {"id": "q_pdd_118", "q": {"ru": "Можно ли перевозить пассажиров в кузове грузового?", "kk": "Ж