t": 2, "explain": {"ru": "Знак ограничивает массу ТС.", "kk": "Белгі көлік массасын шектейді."}}, {"id": "q_pdd_123", "q": {"ru": "Как проехать участок с дорожными работами?", "kk": "Жол жұмыстары бар учаскені қалай өту керек?"}, "options": [{"ru": "С той же скоростью", "kk": "Сол жылдамдықпен"}, {"ru": "Снизить скорость и следовать указаниям", "kk": "Жылдамдықты төмендетіп, нұсқауларға сүйену"}, {"ru": "Объехать по встречной всегда", "kk": "Әрқашан қарсы жолақпен айналу"}], "correct": 1, "explain": {"ru": "На работах — снижать скорость и слушать регулировщика.", "kk": "Жұмыстарда — жылдамдықты төмендетіп, реттеушіні тыңдау."}}, {"id": "q_pdd_124", "q": {"ru": "Разрешена ли езда без номеров?", "kk": "Нөмірсіз жүруге рұқсат па?"}, "options": [{"ru": "Да", "kk": "Иә"}, {"ru": "Нет", "kk": "Жоқ"}, {"ru": "Только в городе", "kk": "Тек қалада"}], "correct": 1, "explain": {"ru": "ТС должно иметь регистрационные знаки.", "kk": "Көліктің тіркеу белгілері болуы керек."}}, {"id": "q_pdd_125", "q": {"ru": "Что делать при проколе колеса на дороге?", "kk": "Жолда дөңгелек тесілгенде не істеу керек?"}, "options": [{"ru": "Остановиться на проезжей части", "kk": "Жол бөлігінде тоқтау"}, {"ru": "Включить аварийку, съехать на обочину, выставить знак", "kk": "Апат сигналын қосып, жол жиегіне шығып, белгі қою"}, {"ru": "Продолжать", "kk": "Жалғастыру"}], "correct": 1, "explain": {"ru": "Нужно безопасно остановиться и обозначить ТС.", "kk": "Қауіпсіз тоқтап, көлікті белгілеу керек."}}, {"id": "q_pdd_126", "q": {"ru": "Как правильно использовать аварийную сигнализацию?", "kk": "Апат сигналын қалай дұрыс қолдану керек?"}, "options": [{"ru": "При вынужденной остановке, ДТП, буксировке", "kk": "Мәжбүрлі тоқтауда, ЖКО, сүйреуде"}, {"ru": "Никогда", "kk": "Ешқашан"}, {"ru": "Всегда", "kk": "Әрқашан"}], "correct": 0, "explain": {"ru": "Аварийка — при остановке, ДТП, буксировке.", "kk": "Апат сигналы — тоқтауда, ЖКО, сүйреуде."}}, {"id": "q_pdd_127", "q": {"ru": "На каком расстоянии выставлять 