нению.", "kk": "Бас тарту мас күйге теңестіріледі."}}, {"id": "q_pdd_141", "q": {"ru": "Как перевозить груз, выступающий за габариты?", "kk": "Габариттен шығып тұрған жүкті қалай тасымалдау керек?"}, "options": [{"ru": "Ночью без света", "kk": "Түнде жарықсыз"}, {"ru": "Без обозначений", "kk": "Белгілеусіз"}, {"ru": "Обозначить и при необходимости получить разрешение", "kk": "Белгілеп, қажет болса рұқсат алу"}], "correct": 2, "explain": {"ru": "Выступающий груз нужно обозначить.", "kk": "Шығып тұрған жүкті белгілеу керек."}}, {"id": "q_pdd_142", "q": {"ru": "Что означает знак «Обгон запрещён» в сочетании с сплошной линией?", "kk": "«Басып озуға тыйым» белгісі тұтас сызықпен бірге нені білдіреді?"}, "options": [{"ru": "Обгон запрещён, выезд на встречную запрещён", "kk": "Басып озуға тыйым, қарсы жолаққа шығуға тыйым"}, {"ru": "Обгон разрешён", "kk": "Басып озу рұқсат"}, {"ru": "Можно обгонять справа", "kk": "Оң жақтан басып озуға болады"}], "correct": 0, "explain": {"ru": "И знак, и сплошная запрещают обгон.", "kk": "Белгі де, тұтас сызық та басып озуға тыйым салады."}}, {"id": "q_pdd_143", "q": {"ru": "Как действовать при гололёде?", "kk": "Көктайғақта қалай әрекет ету керек?"}, "options": [{"ru": "Резко тормозить и газовать", "kk": "Күрт тежеп, газ беру"}, {"ru": "Плавно управлять, увеличить дистанцию, избегать резких манёвров", "kk": "Жұмсақ басқарып, арақашықтықты ұлғайтып, күрт маневрлерден аулақ болу"}, {"ru": "Ехать как обычно", "kk": "Әдеттегідей жүру"}], "correct": 1, "explain": {"ru": "На гололёде — плавность и большая дистанция.", "kk": "Көктайғақта — жұмсақтық және үлкен арақашықтық."}}, {"id": "q_pdd_144", "q": {"ru": "Разрешена ли стоянка на тротуаре?", "kk": "Жол жиегінде тұраққа рұқсат па?"}, "options": [{"ru": "Только если есть разрешающий знак", "kk": "Тек рұқсат беретін белгі болса"}, {"ru": "Да, всегда", "kk": "Иә, әрқашан"}, {"ru": "Никогда", "kk": "Ешқашан"}], "correct": 0, "explain": {"ru": "На тротуаре — только по знаку.", "kk": "Жол жиегінде — тек белгі бойынша."}}, {"id": "q_pdd_145", "q": {"ru": "Что должен сделать водитель перед началом движения?", "kk": "Қозғалысты бастамас бұрын жүргізуші не істеуі керек?"}, "options": [{"ru": "Ничего", "kk": "Ештеңе"}, {"ru": "Убедиться в безопасности и включить поворотник", "kk": "Қауіпсіздікті тексеріп, бұрылыс сигналын қосу"}, {"ru": "Сразу газовать", "kk": "Бірден газ беру"}], "correct": 2, "explain": {"ru": "Перед стартом — осмотр и сигнал.", "kk": "Бастар алдында — қарау және сигнал."}}, {"id": "q_pdd_146", "q": {"ru": "Как правильно обгонять на двухполосной дороге?", "kk": "Екі жолақты жолда қалай дұрыс басып озу керек?"}, "options": [{"ru": "Не сигналя", "kk": "Сигнал бермей"}, {"ru": "Справа", "kk": "Оң жақтан"}, {"ru": "Выехать на встречную, убедившись в безопасности, и вернуться", "kk": "Қауіпсіздікті тексеріп, қарсы жолаққа шығып, қайту"}], "correct": 2, "explain": {"ru": "Обгон — с выездом на встречную при безопасности.", "kk": "Басып озу — қауіпсіз болса қарсы жолаққа шығып."}}, {"id": "q_pdd_147", "q": {"ru": "Что означает прерывистая линия разметки?", "kk": "Үзік сызықты белгілеу нені білдіреді?"}, "options": [{"ru": "Разрешено перестроение и обгон при безопасности", "kk": "Қауіпсіз болса қатар ауыстыру мен басып озу рұқсат"}, {"ru": "Выезд запрещён", "kk": "Шығуға тыйым"}, {"ru": "Стоп", "kk": "Тоқта"}], "correct": 0, "explain": {"ru": "Прерывистая разрешает перестроение.", "kk": "Үзік сызық қатар ауыстыруға рұқсат береді."}}, {"id": "q_pdd_148", "q": {"ru": "Что означает сплошная линия разметки?", "kk": "Тұтас сызықты белгілеу нені білдіреді?"}, "options": [{"ru": "Пересекать запрещено", "kk": "Кесіп өтуге тыйым"}, {"ru": "Только для пешеходов", "kk": "Тек жаяу жүргіншілерге"}, {"ru": "Можно пересекать", "kk": "Кесіп өтуге болады"}], "correct": 0, "explain": {"ru": "Сплошную пересекать нельзя.", "kk": "Тұтас сызықты кесіп өтуге болмайды."}}, {"id": "q_pdd_149", "q": {"ru": "Как действовать на перекрёстке с круговым движением без знаков?", "kk": "Белгісіз айналма қиылыста қалай әрекет ету керек?"}, "options": [{"ru": "Ехать против часовой", "kk": "Сағат тіліне қарсы"}, {"ru": "Уступить помехе справа / уже находящимся на круге по ситуации", "kk": "Оң кедергіге / шеңбердегілерге жағдайға қарай жол беру"}, {"ru": "Въезжающий всегда первый", "kk": "Кіретін әрқашан бірінші"}], "correct": 1, "explain": {"ru": "Без знаков действуют общие правила приоритета.", "kk": "Белгісіз жалпы басымдық ережелері қолданылады."}}, {"id": "q_pdd_150", "q": {"ru": "Разрешена ли остановка на остановке общественного транспорта?", "kk": "Қоғамдық көлік аялдамасында тоқтауға рұқсат па?"}, "options": [{"ru": "Да, всегда", "kk": "Иә, әрқашан"}, {"ru": "Только ночью", "kk": "Тек түнде"}, {"ru": "Нет, кроме посадки/высадки без помехи", "kk": "Жоқ, кедергісіз отырғызу/түсіруден басқа"}], "correct": 2, "explain": {"ru": "На остановке стоянка запрещена.", "kk": "Аялдамада тұраққа тыйым."}}, {"id": "q_pdd_151", "q": {"ru": "Что обязан сделать водитель, сбивший животное?", "kk": "Жануарды қағып кеткен жүргізуші не істеуге міндетті?"}, "options": [{"ru": "Остановиться и действовать по правилам (при ущербе — оформить)", "kk": "Тоқтап, ереже бойынша әрекет ету (залал болса — ресімдеу)"}, {"ru": "Ничего", "kk": "Ештеңе"}, {"ru": "Уехать", "kk": "Кетіп қалу"}], "correct": 0, "explain": {"ru": "При наезде нужно остановиться и оформить при необходимости.", "kk": "Қағып кеткенде тоқтап, қажет болса ресімдеу керек."}}, {"id": "q_pdd_152", "q": {"ru": "Как правильно использовать звуковой сигнал?", "kk": "Дыбыс сигналын қалай дұрыс қолдану керек?"}, "options": [{"ru": "Всегда в городе", "kk": "Қалада әрқашан"}, {"ru": "Никогда", "kk": "Ешқашан"}, {"ru": "Для предотвращения ДТП и вне населённого пункта для предупреждения", "kk": "ЖКО алдын алу үшін және елді мекеннен тыс ескерту үшін"}], "correct": 2, "explain": {"ru": "Сигнал — для предупреждения об опасности.", "kk": "Сигнал — қауіп туралы ескерту үшін."}}, {"id": "q_pdd_153", "q": {"ru": "Что означает знак «Рекомендуемая скорость»?", "kk": "«Ұсынылатын жылдамдық» белгісі нені білдіреді?"}, "options": [{"ru": "Минимальная скорость", "kk": "Ең төменгі жылдамдық"}, {"ru": "Рекомендуемая скорость", "kk": "Ұсынылатын жылдамдық"}, {"ru": "Обязательный лимит", "kk": "Міндетті шек"}], "correct": 1, "explain": {"ru": "Это рекомендация, не запрет.", "kk": "Бұл ұсыныс, тыйым емес."}}, {"id": "q_pdd_154", "q": {"ru": "Можно ли двигаться по полосе для маршрутных ТС?", "kk": "Бағыттық көліктер жолағымен жүруге бола ма?"}, "options": [{"ru": "Только если разрешено знаком или для поворота", "kk": "Тек белгімен рұқсат етілсе немесе бұрылу үшін"}, {"ru": "Да, всегда", "kk": "Иә, әрқашан"}, {"ru": "Никогда", "kk": "Ешқашан"}], "correct": 0, "explain": {"ru": "Полоса для автобусов — с ограничениями.", "kk": "Автобус жолағы — шектеулермен."}}, {"id": "q_pdd_155", "q": {"ru": "Что делать при отказе тормозов?", "kk": "Тежегіш істен шыққанда не істеу керек?"}, "options": [{"ru": "Продолжать", "kk": "Жалғастыру"}, {"ru": "Газовать", "kk": "Газ беру"}, {"ru": "Использовать ручной тормоз, пониженные передачи, аварийку", "kk": "Қол тежегішін, төмен берілістерді, апат сигналын қолдану"}], "correct": 2, "explain": {"ru": "При отказе тормозов — ручник и пониженные передачи.", "kk": "Тежегіш істен шыққанда — қол тежегіш және төмен берілістер."}}, {"id": "q_pdd_156", "q": {"ru": "Как правильно обгонять колонну?", "kk": "Колоннаны қалай дұрыс басып озу керек?"}, "options": [{"ru": "Целиком, убедившись в безопасности", "kk": "Тұтастай, қауіпсіздікті тексеріп"}, {"ru": "Справа", "kk": "Оң жақтан"}, {"ru": "Между машинами", "kk": "Көліктер арасында"}], "correct": 0, "explain": {"ru": "Колонну обгоняют целиком при безопасности.", "kk": "Колоннаны қауіпсіз болса тұтастай басып озады."}}, {"id": "q_pdd_157", "q": {"ru": "Что означает знак «Конец всех ограничений»?", "kk": "«Барлық шектеулердің соңы» белгісі нені білдіреді?"}, "options": [{"ru": "Отменяются ранее введённые ограничения", "kk": "Бұрын енгізілген шектеулер жойылады"}, {"ru": "Начало ограничений", "kk": "Шектеулердің басы"}, {"ru": "Стоп", "kk": "Тоқта"}], "correct": 0, "explain": {"ru": "Знак отменяет предыдущие ограничения.", "kk": "Белгі алдыңғы шектеулерді жояды."}}, {"id": "q_pdd_158", "q": {"ru": "Разрешена ли перевозка пассажиров в прицепе?", "kk": "Тіркемеде жолаушы тасымалдауға рұқсат па?"}, "options": [{"ru": "Да", "kk": "Иә"}, {"ru": "Нет", "kk": "Жоқ"}, {"ru": "Только детей", "kk": "Тек балаларды"}], "correct": 1, "explain": {"ru": "В прицепе пассажиров перевозить нельзя.", "kk": "Тіркемеде жолаушы тасымалдауға болмайды."}}, {"id": "q_pdd_159", "q": {"ru": "Что должен знать водитель о знаке «Уступите дорогу» на круге?", "kk": "Шеңбердегі «Жол беріңіз» белгісі туралы жүргізуші не білуі керек?"}, "options": [{"ru": "Он должен уступить движущимся по кругу", "kk": "Ол шеңберде жүріп жатқандарға жол беруі керек"}, {"ru": "Он имеет преимущество", "kk": "Оның басымдығы бар"}, {"ru": "Знак не действует", "kk": "Белгі әрекет етпейді"}], "correct": 0, "explain": {"ru": "Знак обязывает уступить.", "kk": "Белгі жол беруді міндеттейді."}}, {"id": "q_pdd_160", "q": {"ru": "Как действовать при тумане?", "kk": "Тұманда қалай әрекет ету керек?"}, "options": [{"ru": "Выключить свет", "kk": "Жарықты өшіру"}, {"ru": "Снизить скорость, включить противотуманные и ближний, увеличить дистанцию", "kk": "Жылдамдықты төмендетіп, тұманға қарсы және жақын жарықты қосып, арақашықтықты ұлғайту"}, {"ru": "Ехать быстро с дальним", "kk": "Алыс жарықпен жылдам жүру"}], "correct": 1, "explain": {"ru": "В тумане — низкая скорость и правильный свет.", "kk": "Тұманда — төмен жылдамдық және дұрыс жарық."}}]'::jsonb as arr
),
existing as (
  select coalesce(data, '[]'::jsonb) as data
  from public.app_state
  where key = 'questions'
),
kept as (
  select elem
  from existing, lateral jsonb_array_elements(existing.data) elem
  where elem->>'id' not like 'q_pdd_%'
),
merged as (
  select coalesce(
    (select jsonb_agg(elem) from kept),
    '[]'::jsonb
  ) || (select arr from new_q) as data
)
insert into public.app_state (key, data)
select 'questions', merged.data from merged
on conflict (key) do update set data = excluded.data, updated_at = now();
